class UnsafeBankAccount {
    public String accountHolder;
    public double balance;
}

class SafeBankAccount {
    private String accountHolder;
    private double balance;

    public SafeBankAccount(String holder, double initialBalance) {
        this.accountHolder = holder;
        if (initialBalance >= 0) {
            this.balance = initialBalance;
        } else {
            this.balance = 0.0;
        }
    }

    public void withdraw(double amount) {
        if (amount <= 0) {
            System.out.println("Withdrawal amount must be positive.");
        } else if (amount > balance) {
            System.out.println("Insufficient funds. Withdrawal rejected.");
        } else {
            balance -= amount;
            System.out.println("Withdrew $" + amount + ". Remaining: $" + balance);
        }
    }

    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        // Unsafe version - data corrupted easily
        UnsafeBankAccount unsafe = new UnsafeBankAccount();
        unsafe.balance = -99999.0; // Disaster! No validation!
        System.out.println("Unsafe Balance: $" + unsafe.balance);

        // Safe encapsulated version - guards in place
        SafeBankAccount safe = new SafeBankAccount("Amina", 500.0);
        safe.withdraw(1000.0); // Safely rejected!
        safe.withdraw(150.0);  // Approved!
        System.out.println("Final Safe Balance: $" + safe.getBalance());
    }
}

