class ProductInventory {
    private String productName;
    private int stockCount;

    public ProductInventory(String name, int initialStock) {
        this.productName = name;
        this.stockCount = Math.max(0, initialStock);
    }

    public void purchase(int quantity) {
        if (quantity <= 0) {
            System.out.println("Invalid order quantity: " + quantity);
            return;
        }
        if (quantity > stockCount) {
            System.out.println("Order failed: Only " + stockCount + " " + productName + " available.");
            return;
        }
        stockCount -= quantity;
        System.out.println("Purchased " + quantity + "x " + productName + ". In stock: " + stockCount);
    }

    public void restock(int quantity) {
        if (quantity > 0) {
            stockCount += quantity;
            System.out.println("Restocked " + quantity + " units. Total stock: " + stockCount);
        }
    }

    public int getStockCount() {
        return stockCount;
    }
}

public class Main {
    public static void main(String[] args) {
        ProductInventory item = new ProductInventory("Mechanical Keyboard", 5);
        item.purchase(2);
        item.purchase(10); // Attempting to purchase more than available
        item.restock(8);
        System.out.println("Verified stock count: " + item.getStockCount());
    }
}

