class Student {
    private int age;

    public Student(int age) {
        setAge(age);
    }

    public void setAge(int age) {
        if (age >= 5 && age <= 100) {
            this.age = age;
        }
    }

    public int getAge() {
        return this.age;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student(18);
        s.setAge(-10); // Ignored due to validation
        s.setAge(21);  // Accepted
        System.out.println("Verified age: " + s.getAge());
    }
}

