class TemperatureSensor {
    private double celsius;

    public TemperatureSensor(double initialCelsius) {
        if (initialCelsius >= -273.15) {
            this.celsius = initialCelsius;
        } else {
            this.celsius = 0.0;
        }
    }

    public void setCelsius(double temp) {
        if (temp >= -273.15) {
            this.celsius = temp;
        }
    }

    public double getCelsius() {
        return this.celsius;
    }
}

public class Main {
    public static void main(String[] args) {
        TemperatureSensor sensor = new TemperatureSensor(25.0);
        sensor.setCelsius(-300.0); // Rejected
        sensor.setCelsius(36.6);   // Accepted
        System.out.println("Current temp: " + sensor.getCelsius() + " C");
    }
}

class DigitalWallet {
    private String ownerName;
    private double balance;

    public DigitalWallet(String ownerName, double initialBalance) {
        this.ownerName = ownerName;
        this.balance = initialBalance >= 0 ? initialBalance : 0.0;
    }

    public void addFunds(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public boolean pay(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    public String getOwnerName() {
        return ownerName;
    }

    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        DigitalWallet wallet = new DigitalWallet("Kavita", 100.0);
        wallet.addFunds(50.0);
        wallet.pay(70.0);
        System.out.println("Wallet owner: " + wallet.getOwnerName() + " | Balance: $" + wallet.getBalance());
    }
}

class LeakyAccount {
    private double balance;

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        LeakyAccount a = new LeakyAccount();
        a.deposit(-500); // Properly rejected
        a.deposit(200.0); // Accepted
        System.out.println("Secure balance: $" + a.getBalance());
    }
}

