class GameHero {
    private String name;
    private int health;

    public GameHero(String name) {
        this.name = name;
        this.health = 100;
    }

    public void takeDamage(int damage) {
        if (damage > 0) {
            health = Math.max(0, health - damage);
        }
    }

    public void heal(int points) {
        if (points > 0 && health > 0) {
            health = Math.min(100, health + points);
        }
    }

    public int getHealth() {
        return health;
    }

    public String getName() {
        return name;
    }
}

public class Main {
    public static void main(String[] args) {
        GameHero hero = new GameHero("Ares");
        hero.takeDamage(40);
        hero.heal(20);
        hero.takeDamage(150);
        System.out.println(hero.getName() + " health: " + hero.getHealth() + " (Defeated)");
    }
}
